def validate_item(item):
    if not isinstance(item, dict) or 'sku' not in item or 'quantity' not in item or 'reorder_point' not in item:
        raise ValueError('Invalid item format')
    if not isinstance(item['sku'], str) or item['sku'] == '':
        raise ValueError('SKU must be a non-empty string')
    if not isinstance(item['quantity'], int) or item['quantity'] < 0:
        raise ValueError('Quantity must be a non-negative integer')
    if not isinstance(item['reorder_point'], int) or item['reorder_point'] < 0:
        raise ValueError('Reorder point must be a non-negative integer')
    return {k: v for k, v in item.items()}

def build_reorder_plan(items):
    validated_items = {}
    for item in items:
        validated_item = validate_item(item)
        if validated_item['sku'] in validated_items:
            raise ValueError('Duplicate SKU found')
        validated_items[validated_item['sku']] = validated_item['quantity']
    reorder_plan = {}
    for sku, item in validated_items.items():
        if item['quantity'] < item['reorder_point']:
            reorder_plan[sku] = 2 * item['reorder_point'] - item['quantity']
    return reorder_plan
